export class ShellService extends ReactiveService {
  drawerOpen = false;
  howToOpen = false;
  place = 'learn';
  openDrawer() {
    this.drawerOpen = true;
    this.__notify();
  }
  closeDrawer() {
    this.drawerOpen = false;
    this.__notify();
  }
  openHowTo() {
    this.drawerOpen = false;
    this.__notify();
    this.howToOpen = true;
    this.__notify();
  }
  closeHowTo() {
    this.howToOpen = false;
    this.__notify();
  }
  setPlace(place: string) {
    this.place = place;
    this.__notify();
  }
}

