      code: '<row *ngFor="let item of items" [title]="item"></row>',
      implementation: '// lists.component.ts\nimport { Component } from \'@angular/core\';\n\n@Component({\n  selector: \'app-lists-demo\',\n  templateUrl: \'./lists.component.html\',\n})\nexport class ListsDemoComponent {\n  items = [\'Morning run\', \'Team standup\', \'Deep work\'];\n  private pool = [\'Evening walk\', \'Reading\', \'Write the report\', \'Water the plants\'];\n  private next = 0;\n\n  add() {\n    const item = this.pool[this.next % this.pool.length];\n    this.next++;\n    this.items = [...this.items, item];\n  }\n\n  removeLast() {\n    this.items = this.items.slice(0, this.items.length - 1);\n  }\n\n  clear() {\n    this.items = [];\n  }\n}\n\n// lists.component.html\n<list>\n  <row *ngFor="let item of items; let i = index" [title]="item" [detail]="\'Item \' + (i + 1)"></row>\n</list>\n<p *ngIf="items.length === 0">The list is empty. ngFor over an empty array renders nothing.</p>\n<p>{{ items.length }} items in the array, {{ items.length }} rows on screen.</p>\n<button (click)="add()">\n  Add an item\n</button>\n<button (click)="removeLast()" [disabled]="items.length === 0">\n  Remove the last\n</button>\n<button (click)="clear()" [disabled]="items.length === 0">\n  Clear the list\n</button>',
      tip: 'Change lists by assignment, never by editing in place. A new array is what tells Rangular to render the list again.',
