export function DeviceKey({ glyph = '', label = '', compact = false, square = false, onPressed }: { glyph?: any; label?: any; compact?: any; square?: any; onPressed?: (value: any) => void }) {
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [dipped, setDipped] = useState(false);
  const press = () => {
    setDipped(true);
    onPressed?.();
    setTimeout(() => {
  setDipped(false);
}, 150);
  };
  __sigTracker.current.begin();
  try {
    return (
      <RgSection style={[styles.deviceKeyBase, compact ? styles.deviceKeyBaseCompact : undefined, square ? styles.deviceKeyBaseSquare : undefined, dipped ? styles.deviceKeyBaseDipped : undefined]}>
        <RgSection onPress={() => press()} style={[styles.deviceKeyFace, square ? styles.deviceKeyFaceSquare : undefined]}>
          <RgText variant="bodyLarge" style={styles.deviceKeyGlyph}>{glyph}</RgText>
          {!!((label !== '')) && (
            <RgText variant="bodyLarge" style={styles.deviceKeyKlabel}>{label}</RgText>
          )}
        </RgSection>
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

