export function HttpBasicsDemo() {
  const api = __container.get<ApiService>(ApiService);
  useSyncExternalStore((cb) => api.__subscribe(cb), () => api.__getVersion());
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [city, setCity] = useState('');
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState('');
  const load = () => {
    setLoading(true);
    setFailed('');
    api.getUser().pipe(map((data: any) => ({ name: data.name, email: data.email, city: data.address.city }))).subscribe((user) => {
  setName(user.name);
  setEmail(user.email);
  setCity(user.city);
  setLoading(false);
}, (err) => {
  setFailed('The request failed. Check the connection and try again.');
  setLoading(false);
});
  };
  const create = () => {
    const body = { name: 'Asha Verma', email: 'asha@example.com' };
    setLoading(true);
    setFailed('');
    api.createUser(body).subscribe((data) => {
  setName(data.name);
  setEmail(data.email);
  setCity('');
  setLoading(false);
}, (err) => {
  setFailed('The request failed. Check the connection and try again.');
  setLoading(false);
});
  };
  const update = () => {
    const body = { name: 'Leanne Graham', email: 'leanne@example.com', address: { city: 'Gwenborough' } };
    setLoading(true);
    setFailed('');
    api.updateUser(body).subscribe((data) => {
  setName(data.name);
  setEmail(data.email);
  setCity(data.address.city);
  setLoading(false);
}, (err) => {
  setFailed('The request failed. Check the connection and try again.');
  setLoading(false);
});
  };
  const remove = () => {
    setLoading(true);
    setFailed('');
    api.deleteUser().subscribe(() => {
  setName('');
  setEmail('');
  setCity('');
  setLoading(false);
}, (err) => {
  setFailed('The request failed. Check the connection and try again.');
  setLoading(false);
});
  };
  useEffect(() => {
    load();
  }, []);
  __sigTracker.current.begin();
  try {
    return (
      <>
        <RgButton disabled={loading} onPress={() => load()}>Load one user</RgButton>
        {!!(loading) && (
          <RgSpinner />
        )}
        {!!(loading) && (
          <RgText variant="bodyLarge">Loading...</RgText>
        )}
        {!!(failed) && (
          <RgText variant="bodyLarge">{failed}</RgText>
        )}
        {!!(name) && (
          <RgSection>
            <RgText variant="bodyLarge">Name: {name}</RgText>
            <RgText variant="bodyLarge">Email: {email}</RgText>
            <RgText variant="bodyLarge">City: {city}</RgText>
          </RgSection>
        )}
      </>
    );
  } finally {
    __sigTracker.current.end();
  }
}

