export function IotSample() {
  const iot = __container.get<IotService>(IotService);
  useSyncExternalStore((cb) => iot.__subscribe(cb), () => iot.__getVersion());
  const router = __router;
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [roomViews, setRoomViews] = useState([]);
  const ngOnInit = () => {
    iot.whenLoaded(() => refresh());
  };
  const refresh = () => {
    setRoomViews(iot.rooms.map((room) => ({ title: room.title, devices: room.devices.map((d: any) => ({ name: d.name, on: d.on, timed: (d.fromIso ? true : false), fromIso: d.fromIso, toIso: d.toIso, state: (d.fromIso ? fmtTime(d.fromIso) + ' to ' + fmtTime(d.toIso) + ((d.on ? ' · Timer on' : ' · Timer off')) : (d.on ? 'On' : 'Off')) })), history: room.history.map((h: any) => ({ text: h.text, ago: ago(h.at) })) })));
  };
  const fmtTime = (iso: string) => {
    const h = Number(iso.slice(11, 13));
    const suffix = (h >= 12 ? 'PM' : 'AM');
    const h12 = (h % 12 === 0 ? 12 : h % 12);
    return h12 + ':' + iso.slice(14, 16) + ' ' + suffix;
  };
  const setFrom = (room: any, d: any, iso: string) => {
    iot.setWindow(room.title, d.name, 'from', iso);
    refresh();
  };
  const setTo = (room: any, d: any, iso: string) => {
    iot.setWindow(room.title, d.name, 'to', iso);
    refresh();
  };
  const ago = (at: number) => {
    const mins = Math.floor((Date.now() - at) / 60000);
    if (mins <= 0) {
      return 'just now';
    }
    if (mins === 1) {
      return '1 min ago';
    }
    if (mins < 60) {
      return mins + ' min ago';
    }
    const hrs = Math.floor(mins / 60);
    return (hrs === 1 ? '1 hour ago' : hrs + ' hours ago');
  };
  const toggle = (room: any, d: any) => {
    iot.toggle(room.title, d.name);
    refresh();
  };
  const goBack = () => {
    router.navigate(['/samples']);
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  __sigTracker.current.begin();
  try {
    return (
      <RgSection>
        <RgAppbar tone="tint" title="Internet of Things Sample" pin back onBack={() => goBack()} />
        {roomViews.map((room, index) => (
          <RgCard key={room?.id ?? index} style={styles.iotSampleRoomCard}>
            <RgSection style={styles.iotSampleRoomHead}>
              <RgText variant="title" style={styles.iotSampleRoomTitle}>{room.title}</RgText>
              <RgSection style={styles.iotSampleCountPill}>
                <RgText variant="bodyLarge" style={styles.iotSampleCountText}>{room.devices.length} devices</RgText>
              </RgSection>
            </RgSection>
            {room.devices.map((d, index) => (
              <RgSection key={d?.id ?? index}>
                <RgSection style={styles.iotSampleDevRow}>
                  <RgSection style={styles.iotSampleDevMain}>
                    <RgText variant="bodyLarge" style={styles.iotSampleDevName}>{d.name}</RgText>
                    <RgText variant="bodyLarge" style={styles.iotSampleDevState}>{d.state}</RgText>
                  </RgSection>
                  <RgSwitch color="success" checked={d.on} onChange={($event) => toggle(room, d)} />
                </RgSection>
                {!!(d.timed) && (
                  <RgSection style={styles.iotSampleWinRow}>
                    <RgSection style={styles.iotSampleWinPick}>
                      <RgDateTimePicker mode="time" label="From" value={d.fromIso} onChange={($event) => setFrom(room, d, $event)} />
                    </RgSection>
                    <RgSection style={styles.iotSampleWinPick}>
                      <RgDateTimePicker mode="time" label="To" value={d.toIso} onChange={($event) => setTo(room, d, $event)} />
                    </RgSection>
                  </RgSection>
                )}
              </RgSection>
            ))}
            <RgText variant="label">History</RgText>
            {!!((room.history.length === 0)) && (
              <RgText variant="bodyLarge" style={styles.iotSampleHist}>No changes yet. Flip a switch above.</RgText>
            )}
            {room.history.map((h, index) => (
              <RgText key={h?.id ?? index} variant="bodyLarge" style={styles.iotSampleHist}>{h.text} · {h.ago}</RgText>
            ))}
          </RgCard>
        ))}
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

export function AlarmSample() {
  const alarm = __container.get<AlarmService>(AlarmService);
  useSyncExternalStore((cb) => alarm.__subscribe(cb), () => alarm.__getVersion());
  const router = __router;
  const snack = __snackBar;
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [titleDraft, setTitleDraft] = useState('');
  const [draftTime, setDraftTime] = useState('');
  const [draftDays, setDraftDays] = useState([]);
  const [draftEnabled, setDraftEnabled] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [cardTitle, setCardTitle] = useState('');
  const [timeLabel, setTimeLabel] = useState('');
  const [ringLabel, setRingLabel] = useState('');
  const [daysLabel, setDaysLabel] = useState('');
  const [bandSub, setBandSub] = useState('');
  const [repeatOpen, setRepeatOpen] = useState(false);
  const [dayRows, setDayRows] = useState([]);
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const dayFullNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const ngOnInit = () => {
    copyDrafts();
  };
  const copyDrafts = () => {
    applyDraft(alarm.timeIso, alarm.title, alarm.days.slice(), alarm.enabled);
  };
  const refresh = () => {
    applyDraft(draftTime, titleDraft, draftDays, draftEnabled);
  };
  const applyDraft = (time: string, title: string, days: number[], enabled: boolean) => {
    setDraftTime(time);
    setTitleDraft(title);
    setDraftDays(days);
    setDraftEnabled(enabled);
    setTimeLabel(fmtTime(time));
    setRingLabel(fmtTime(alarm.timeIso));
    const ct = (title === '' ? 'Alarm' : title);
    const dl = computeDaysLabel(days);
    setCardTitle(ct);
    setDaysLabel(dl);
    setBandSub(ct + ' · ' + dl);
    setDayRows([0, 1, 2, 3, 4, 5, 6].map((d) => ({ d, name: dayFullNames[d], on: days.indexOf(d) >= 0 })));
    setDirty(time.slice(11) !== alarm.timeIso.slice(11) || title !== alarm.title || days.join(',') !== alarm.days.join(',') || enabled !== alarm.enabled);
  };
  const fmtTime = (iso: string) => {
    const h = Number(iso.slice(11, 13));
    const suffix = (h >= 12 ? 'PM' : 'AM');
    const h12 = (h % 12 === 0 ? 12 : h % 12);
    return h12 + ':' + iso.slice(14, 16) + ' ' + suffix;
  };
  const computeDaysLabel = (days: number[]) => {
    if (days.length === 0) {
      return 'Never';
    }
    if (days.length === 7) {
      return 'Every day';
    }
    if (days.length === 5 && days.indexOf(1) >= 0 && days.indexOf(5) >= 0 && days.indexOf(0) < 0 && days.indexOf(6) < 0) {
      return 'Weekdays';
    }
    if (days.length === 2 && days.indexOf(0) >= 0 && days.indexOf(6) >= 0) {
      return 'Weekends';
    }
    return dayNames.filter((n, i) => days.indexOf(i) >= 0).join(', ');
  };
  const setTime = (iso: string) => {
    applyDraft(iso, titleDraft, draftDays, draftEnabled);
  };
  const applyTitle = (v: string) => {
    applyDraft(draftTime, v.slice(0, 50), draftDays, draftEnabled);
  };
  const toggleDay = (d: number) => {
    const next = (draftDays.indexOf(d) >= 0 ? draftDays.filter((x) => x !== d) : draftDays.concat([d]));
    applyDraft(draftTime, titleDraft, next, draftEnabled);
  };
  const save = () => {
    alarm.save(draftTime, titleDraft, draftDays, draftEnabled);
    if (!alarm.enabled) {
      snack.open('Alarm saved. It is off.');
    } else if (alarm.days.length === 0) {
      snack.open('Alarm saved. Pick at least one day to make it ring.');
    } else {
      snack.open('Alarm saved. It will ring ' + alarm.nextDayWord() + ' at ' + fmtTime(alarm.timeIso) + '.');
    }
    copyDrafts();
    refresh();
  };
  const openRepeat = () => {
    setRepeatOpen(true);
  };
  const closeRepeat = () => {
    setRepeatOpen(false);
  };
  const onSwitch = (v: boolean) => {
    applyDraft(draftTime, titleDraft, draftDays, v);
  };
  const stop = () => {
    alarm.stopRing();
    refresh();
  };
  const snooze = () => {
    alarm.snooze();
    refresh();
  };
  const goBack = () => {
    router.navigate(['/samples']);
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  __sigTracker.current.begin();
  try {
    return (
      <RgSection>
        <RgAppbar tone="tint" title="Alarm" pin back onBack={() => goBack()} />
        {!!(alarm.ringing) && (
          <RgSection>
            <RgSection style={styles.alarmSampleRingBand}>
              <RgText variant="bodyLarge" style={styles.alarmSampleRingLabel}>ALARM</RgText>
              <RgText variant="bodyLarge" style={styles.alarmSampleRingTime}>{ringLabel}</RgText>
              <RgText variant="bodyLarge" style={styles.alarmSampleRingTitle}>{alarm.title}</RgText>
              <RgSection style={styles.alarmSampleRingActions}>
                <RgButton color="danger" onPress={() => stop()}>Stop</RgButton>
                <RgButton color="neutral" onPress={() => snooze()}>Snooze 5 min</RgButton>
              </RgSection>
            </RgSection>
          </RgSection>
        )}
        {!!(!alarm.ringing) && (
          <RgSection>
            <RgSection style={styles.alarmSampleBand}>
              <RgSection style={styles.alarmSampleBandTop}>
                <RgText variant="bodyLarge" style={styles.alarmSampleEyebrow}>ALARM</RgText>
                <RgSwitch color="success" checked={draftEnabled} onChange={($event) => onSwitch($event)} />
              </RgSection>
              <RgText variant="bodyLarge" style={styles.alarmSampleBandTime}>{timeLabel}</RgText>
              <RgText variant="bodyLarge" style={styles.alarmSampleBandSub}>{bandSub}</RgText>
            </RgSection>
            <RgCard style={styles.alarmSampleSettingsCard}>
              <RgDateTimePicker mode="time" label="When" value={draftTime} onChange={($event) => setTime($event)} />
              <RgSection onPress={() => openRepeat()} style={styles.alarmSampleSetRow}>
                <RgSection style={styles.alarmSampleSetIc}>
                  <RgIcon name="calendar" color="primary" />
                </RgSection>
                <RgSection style={styles.alarmSampleSetMain}>
                  <RgText variant="bodyLarge" style={styles.alarmSampleSetLabel}>Repeat</RgText>
                  <RgText variant="bodyLarge" style={styles.alarmSampleSetValue}>{daysLabel}</RgText>
                </RgSection>
                <RgSection style={styles.alarmSampleSetChev}>
                  <RgIcon name="chevron-right" color="primary" />
                </RgSection>
              </RgSection>
              <RgInput label="Alarm title" placeholder="Wake up" value={titleDraft} onChangeText={($event) => { setTitleDraft($event); applyTitle($event); }} />
              {!!((titleDraft.length > 40)) && (
                <RgText variant="bodyLarge">{(50 - titleDraft.length)} characters left.</RgText>
              )}
              {!!(dirty) && (
                <RgButton onPress={() => save()}>Save alarm</RgButton>
              )}
            </RgCard>
            <RgText variant="bodyLarge" style={styles.alarmSampleNote}>It rings on this page while the app is open, with vibration.</RgText>
          </RgSection>
        )}
        <RgDialog title="Repeat" open={repeatOpen} onClose={() => closeRepeat()}>
          {dayRows.map((r, index) => (
            <RgSection key={r?.id ?? index} onPress={() => toggleDay(r.d)} style={styles.alarmSampleDayRow}>
              <RgText variant="bodyLarge" style={styles.alarmSampleDayName}>{r.name}</RgText>
              <RgSection style={[styles.alarmSampleCheck, r.on ? styles.alarmSampleCheckDone : undefined]}>
                {!!(r.on) && (
                  <RgIcon name="check" color="onPrimary" />
                )}
              </RgSection>
            </RgSection>
          ))}
          <RgActions>
            <RgButton onPress={() => closeRepeat()}>Done</RgButton>
          </RgActions>
        </RgDialog>
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

export function TodoSample() {
  const todos = __container.get<TodoService>(TodoService);
  useSyncExternalStore((cb) => todos.__subscribe(cb), () => todos.__getVersion());
  const router = __router;
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [draft, setDraft] = useState('');
  const [draftDesc, setDraftDesc] = useState('');
  const [draftDueOn, setDraftDueOn] = useState(false);
  const [draftDue, setDraftDue] = useState('');
  const [draftPrio, setDraftPrio] = useState(1);
  const [filter, setFilter] = useState('all');
  const [addOpen, setAddOpen] = useState(false);
  const [editingId, setEditingId] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);
  const [menuTarget, setMenuTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleteText, setDeleteText] = useState('');
  const [rows, setRows] = useState([]);
  const [leftCount, setLeftCount] = useState(0);
  const [doneCount, setDoneCount] = useState(0);
  const [totalCount, setTotalCount] = useState(0);
  const ngOnInit = () => {
    todos.whenLoaded(() => refresh('all'));
  };
  const rowOf = (t: any) => {
    const info = todos.dueInfo(t.due, t.done);
    return { id: t.id, text: t.text, prio: t.prio, done: t.done, desc: t.desc, due: t.due, dueText: info.text, overdue: info.overdue };
  };
  const refresh = (f: string) => {
    let __shadowTotalCount = totalCount;
    let __shadowDoneCount = doneCount;
    const all = todos.items;
    __shadowTotalCount = all.length;
    setTotalCount(__shadowTotalCount);
    __shadowDoneCount = all.filter((t) => t.done).length;
    setDoneCount(__shadowDoneCount);
    setLeftCount(__shadowTotalCount - __shadowDoneCount);
    if (f === 'active') {
      setRows(all.filter((t) => !t.done).map((t) => rowOf(t)));
    } else if (f === 'done') {
      setRows(all.filter((t) => t.done).map((t) => rowOf(t)));
    } else {
      setRows(all.map((t) => rowOf(t)));
    }
  };
  const pickFilter = (f: string) => {
    setFilter(f);
    refresh(f);
  };
  const setPrio = (p: number) => {
    setDraftPrio(p);
  };
  const openAdd = () => {
    setEditingId(0);
    setDraft('');
    setDraftDesc('');
    setDraftPrio(1);
    setDraftDueOn(false);
    setDraftDue(todos.todayIso());
    setAddOpen(true);
  };
  const openMenu = (t: any) => {
    setMenuTarget(t);
    setMenuOpen(true);
  };
  const closeMenu = () => {
    setMenuOpen(false);
  };
  const startEdit = () => {
    const t = menuTarget;
    setMenuOpen(false);
    if (!t) {
      return;
    }
    setEditingId(t.id);
    setDraft(t.text);
    setDraftDesc(t.desc);
    setDraftPrio(t.prio);
    setDraftDueOn(t.due !== '');
    setDraftDue((t.due !== '' ? t.due : todos.todayIso()));
    setAddOpen(true);
  };
  const askDelete = () => {
    const t = menuTarget;
    setMenuOpen(false);
    if (!t) {
      return;
    }
    setDeleteTarget(t);
    setDeleteText('This deletes ' + t.text + ' for good. There is no undo.');
  };
  const cancelDelete = () => {
    setDeleteTarget(null);
  };
  const confirmDelete = () => {
    if (deleteTarget) {
      todos.remove(deleteTarget.id);
    }
    setDeleteTarget(null);
    refresh(filter);
  };
  const setDueOn = (v: boolean) => {
    setDraftDueOn(v);
  };
  const setDue = (iso: string) => {
    setDraftDue(iso);
  };
  const closeAdd = () => {
    setAddOpen(false);
  };
  const save = () => {
    if (!draft.trim()) {
      return;
    }
    const f = (filter === 'done' ? 'all' : filter);
    if (editingId > 0) {
      todos.update(editingId, draft, draftPrio, draftDesc, (draftDueOn ? draftDue : ''));
    } else {
      todos.add(draft, draftPrio, draftDesc, (draftDueOn ? draftDue : ''));
    }
    setDraft('');
    setDraftDesc('');
    setDraftDueOn(false);
    setEditingId(0);
    setFilter(f);
    setAddOpen(false);
    refresh(f);
  };
  const toggle = (t: any) => {
    todos.toggle(t.id);
    refresh(filter);
  };
  const goBack = () => {
    router.navigate(['/samples']);
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  __sigTracker.current.begin();
  try {
    return (
      <RgSection>
        <RgAppbar tone="tint" title="Todo list" actionIcon="plus" pin back onBack={() => goBack()} onAction={() => openAdd()} />
        <RgSection style={styles.todoSampleChipsRow}>
          <RgSection onPress={() => pickFilter('all')} style={[styles.todoSampleChip, (filter === 'all') ? styles.todoSampleChipOn : undefined]}>
            <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (filter === 'all') ? styles.todoSampleChipTextOn : undefined]}>All · {totalCount}</RgText>
          </RgSection>
          <RgSection onPress={() => pickFilter('active')} style={[styles.todoSampleChip, (filter === 'active') ? styles.todoSampleChipOn : undefined]}>
            <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (filter === 'active') ? styles.todoSampleChipTextOn : undefined]}>Active · {leftCount}</RgText>
          </RgSection>
          <RgSection onPress={() => pickFilter('done')} style={[styles.todoSampleChip, (filter === 'done') ? styles.todoSampleChipOn : undefined]}>
            <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (filter === 'done') ? styles.todoSampleChipTextOn : undefined]}>Done · {doneCount}</RgText>
          </RgSection>
        </RgSection>
        {!!((rows.length === 0)) && (
          <RgText variant="bodyLarge">Nothing in this view. Switch the filter, or add a task below.</RgText>
        )}
        {rows.map((t, index) => (
          <RgCard key={t?.id ?? index} style={styles.todoSampleTaskCard}>
            <RgSection onPress={() => toggle(t)} style={styles.todoSampleCheckHit}>
              <RgSection style={[styles.todoSampleCheck, t.done ? styles.todoSampleCheckDone : undefined]}>
                {!!(t.done) && (
                  <RgIcon name="check" color="onPrimary" />
                )}
              </RgSection>
            </RgSection>
            <RgSection style={styles.todoSampleTaskMain}>
              <RgText variant="bodyLarge" style={[styles.todoSampleTaskText, t.done ? styles.todoSampleTaskDone : undefined]}>{t.text}</RgText>
              {!!(t.desc) && (
                <RgText variant="bodyLarge" style={[styles.todoSampleTaskDesc, t.done ? styles.todoSampleTaskDone : undefined]}>{t.desc}</RgText>
              )}
              <RgSection style={styles.todoSampleMetaRow}>
                <RgSection style={[styles.todoSamplePrioPill, (t.prio === 2) ? styles.todoSamplePpHigh : undefined, (t.prio === 1) ? styles.todoSamplePpMed : undefined, (t.prio === 0) ? styles.todoSamplePpLow : undefined]}>
                  <RgSection style={[styles.todoSampleDot, (t.prio === 2) ? styles.todoSamplePHigh : undefined, (t.prio === 1) ? styles.todoSamplePMed : undefined, (t.prio === 0) ? styles.todoSamplePLow : undefined]} />
                  <RgText variant="bodyLarge" style={styles.todoSamplePrioText}>{((t.prio === 2) ? 'High priority' : ((t.prio === 1) ? 'Medium priority' : 'Low priority'))}</RgText>
                </RgSection>
                {!!(t.dueText) && (
                  <RgText variant="bodyLarge" style={[styles.todoSampleDueText, t.overdue ? styles.todoSampleDueOver : undefined]}>{t.dueText}</RgText>
                )}
              </RgSection>
            </RgSection>
            <RgSection onPress={() => openMenu(t)} style={styles.todoSampleMoreHit}>
              <RgIcon name="more-vert" color="textMuted" />
            </RgSection>
          </RgCard>
        ))}
        <RgSheet open={addOpen} onClose={() => closeAdd()}>
          <RgSection style={styles.todoSampleSheetWrap}>
            <RgText variant="title">{((editingId > 0) ? 'Edit task' : 'Add a task')}</RgText>
            <RgInput label="Task" placeholder="What needs doing?" value={draft} onChangeText={($event) => setDraft($event)} />
            <RgInput label="Description" placeholder="A few details (optional)" value={draftDesc} onChangeText={($event) => setDraftDesc($event)} />
            <RgSection style={styles.todoSampleDueRow}>
              <RgSection style={styles.todoSampleDueIc}>
                <RgIcon name="calendar" color="primary" />
              </RgSection>
              <RgText variant="bodyLarge" style={styles.todoSampleDueLabel}>Deadline</RgText>
              <RgSwitch color="success" checked={draftDueOn} onChange={($event) => setDueOn($event)} />
            </RgSection>
            {!!(draftDueOn) && (
              <RgDateTimePicker mode="date" label="Due date" value={draftDue} onChange={($event) => setDue($event)} />
            )}
            <RgSection style={styles.todoSampleChipsRow}>
              <RgSection onPress={() => setPrio(0)} style={[styles.todoSampleChip, (draftPrio === 0) ? styles.todoSampleChipOn : undefined]}>
                <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (draftPrio === 0) ? styles.todoSampleChipTextOn : undefined]}>Low</RgText>
              </RgSection>
              <RgSection onPress={() => setPrio(1)} style={[styles.todoSampleChip, (draftPrio === 1) ? styles.todoSampleChipOn : undefined]}>
                <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (draftPrio === 1) ? styles.todoSampleChipTextOn : undefined]}>Medium</RgText>
              </RgSection>
              <RgSection onPress={() => setPrio(2)} style={[styles.todoSampleChip, (draftPrio === 2) ? styles.todoSampleChipOn : undefined]}>
                <RgText variant="bodyLarge" style={[styles.todoSampleChipText, (draftPrio === 2) ? styles.todoSampleChipTextOn : undefined]}>High</RgText>
              </RgSection>
            </RgSection>
            <RgActions>
              <RgButton variant="text" onPress={() => closeAdd()}>Cancel</RgButton>
              <RgButton onPress={() => save()}>{((editingId > 0) ? 'Save changes' : 'Add task')}</RgButton>
            </RgActions>
          </RgSection>
        </RgSheet>
        <RgMenu open={menuOpen} onClose={() => closeMenu()}>
          <RgMenuItem icon="edit" onPress={() => startEdit()}>Edit</RgMenuItem>
          <RgDivider />
          <RgMenuItem icon="delete" onPress={() => askDelete()}>Delete</RgMenuItem>
        </RgMenu>
        <RgDialog title="Delete this task?" open={(deleteTarget !== null)} onClose={() => cancelDelete()}>
          <RgText variant="bodyLarge">{deleteText}</RgText>
          <RgActions>
            <RgButton variant="text" onPress={() => cancelDelete()}>Cancel</RgButton>
            <RgButton color="danger" onPress={() => confirmDelete()}>Delete</RgButton>
          </RgActions>
        </RgDialog>
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

export function NotFound() {
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  __sigTracker.current.begin();
  try {
    return (
      <RgSection>
        <RgText variant="title">Page not found</RgText>
        <RgText variant="bodyLarge">The page you asked for does not exist in this tutorial.</RgText>
        <RgButton variant="text" onPress={() => __router.navigateByUrl("/home")}>Go to the lessons</RgButton>
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

export function Stack() {
  const route = useContext(ActivatedRouteContext) ?? new ActivatedRoute({});
  const router = __router;
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const [langs, setLangs] = useState([]);
  const [first, setFirst] = useState('');
  const [last, setLast] = useState('');
  const ngOnInit = () => {
    let __shadowLangs = langs;
    const raw = route.snapshot.params.langs;
    __shadowLangs = (raw ? raw.split(',') : []);
    setLangs(__shadowLangs);
    if (__shadowLangs.length > 0) {
      setFirst(__shadowLangs[0]);
      setLast(__shadowLangs[__shadowLangs.length - 1]);
    }
  };
  const goBack = () => {
    router.navigate(['/lesson', 60]);
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  __sigTracker.current.begin();
  try {
    return (
      <RgSection>
        <RgAppbar tone="tint" title="Language stack" pin back onBack={() => goBack()} />
        <RgText variant="bodyLarge">The array crossed the route whole. This page rebuilt it from the address and put it to work:</RgText>
        <RgCard>
          <RgText variant="bodyLarge">{langs.length} languages arrived.</RgText>
          <RgList>
            {langs.map((lang, index) => (
              <RgRow key={lang?.id ?? index} title={lang} />
            ))}
          </RgList>
          <RgText variant="bodyLarge">First: {first} · Last: {last}</RgText>
        </RgCard>
        <RgText variant="bodyLarge">One route parameter carried the whole array as one joined string. The page split it back into a list, counted it, and read its ends.</RgText>
      </RgSection>
    );
  } finally {
    __sigTracker.current.end();
  }
}

export default function App() {
  const shell = __container.get<ShellService>(ShellService);
  useSyncExternalStore((cb) => shell.__subscribe(cb), () => shell.__getVersion());
  const router = __router;
  const [__route, __setRoute] = useState(__navigator.current);
  useEffect(() => __navigator.subscribe(() => __setRoute(__navigator.current)), []);
  const [__snack, __setSnack] = useState(__snackBar.current);
  useEffect(() => __snackBar.subscribe(() => __setSnack(__snackBar.current)), []);
  const [, __sigBump] = useReducer((n: number) => n + 1, 0);
  const __sigTracker = useRef(new SignalRenderTracker(__sigBump));
  useEffect(() => () => { __sigTracker.current.dispose(); }, []);
  const closeDrawer = () => {
    shell.closeDrawer();
  };
  const openHowTo = () => {
    shell.openHowTo();
  };
  const closeHowTo = () => {
    shell.closeHowTo();
  };
  const goLearn = () => {
    shell.closeDrawer();
    router.navigate(['/home']);
  };
  const goSaved = () => {
    shell.closeDrawer();
    router.navigate(['/saved']);
  };
  const goHistory = () => {
    shell.closeDrawer();
    router.navigate(['/history']);
  };
  const goSamples = () => {
    shell.closeDrawer();
    router.navigate(['/samples']);
  };
  const goAbout = () => {
    shell.closeDrawer();
    router.navigate(['/about']);
  };
  __sigTracker.current.begin();
  try {
    return (
      <>
        <RgScreen scrollKey={__route.path} fade>
          <RgDrawer open={shell.drawerOpen} onClose={() => closeDrawer()}>
            <RgSection style={styles.drawerHead}>
              <RgText variant="title">Rangular Tutorial</RgText>
              <RgText variant="bodyLarge" style={styles.drawerSub}>98 lessons · Learn by running code</RgText>
              <RgGradient style={styles.drawerRule} />
            </RgSection>
            <RgList>
              <RgRow icon="home" title="Learn" selected={(shell.place === 'learn')} onPress={() => goLearn()} />
              <RgRow icon="bookmark" title="Saved lessons" selected={(shell.place === 'saved')} onPress={() => goSaved()} />
              <RgRow icon="history" title="History" selected={(shell.place === 'history')} onPress={() => goHistory()} />
              <RgRow icon="info" title="How to use this tutorial" onPress={() => openHowTo()} />
              <RgRow icon="play" title="Samples" selected={(shell.place === 'samples')} onPress={() => goSamples()} />
              <RgRow icon="info" title="About" selected={(shell.place === 'about')} onPress={() => goAbout()} />
            </RgList>
            <RgText variant="bodyLarge" style={styles.drawerVersion}>Rangular framework 0.7.0</RgText>
          </RgDrawer>
          <RgDialog title="How to use this tutorial" open={shell.howToOpen} onClose={() => closeHowTo()}>
            <RgText variant="bodyLarge">Start at Lesson 1 and go in order. Tap a lesson, read it, try its demo, then mark it done and move to the next one.</RgText>
            <RgText variant="bodyLarge">Use the search on Home to find one topic. Tap the bookmark icon on a lesson row, or on the lesson screen itself, to save the lesson. Your saved lessons live on the Saved tab, your recent lessons and progress live on the History tab, and small working apps built with Rangular live on the Samples tab.</RgText>
            <RgActions>
              <RgButton variant="text" onPress={() => closeHowTo()}>Got it</RgButton>
            </RgActions>
          </RgDialog>
          <RgOutlet>
            {__route.routePath === "splash" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Splash key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "home" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Home key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "saved" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Saved key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "history" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <History key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "lesson/:id" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Lesson key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "samples" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Samples key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "samples/iot" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <IotSample key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "samples/alarm" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <AlarmSample key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "samples/todo" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <TodoSample key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "about" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <About key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "stack/:langs" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <Stack key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
            {__route.routePath === "**" && (
              <ActivatedRouteContext.Provider value={new ActivatedRoute(__route.params, __navigator)}>
                <NotFound key={__route.path} />
              </ActivatedRouteContext.Provider>
            )}
          </RgOutlet>
        </RgScreen>
        {__snack && (<RgSnackbar message={__snack.message} actionLabel={__snack.actionLabel} onAction={() => __snackBar.pressAction()} />)}
      </>
    );
  } finally {
    __sigTracker.current.end();
  }
}

